import {units,lessons} from './data.mjs';
import {parse,flowchart,hierarchy,classDiagram,escapeHTML as e} from './engine.mjs';
const $=s=>document.querySelector(s),view=$('#view');
let stored={},storageWorks=true;try{stored=JSON.parse(localStorage.getItem('logiclab-progress-v1')||'{}');if(!stored||typeof stored!=='object')stored={};}catch{storageWorks=false;}
let completed=new Set(Array.isArray(stored.completed)?stored.completed.filter(id=>lessons.some(l=>l.id===id)):[]);
let states=new Map(),activeLesson=null,activeTab='theory';
function save(){try{localStorage.setItem('logiclab-progress-v1',JSON.stringify({completed:[...completed]}));}catch{storageWorks=false;}updateProgress();}
function updateProgress(){ $('#progress-count').textContent=`${completed.size} / ${lessons.length}`;$('#course-progress').value=completed.size;$('#course-progress').max=lessons.length;$('#course-progress').textContent=Math.round(completed.size/lessons.length*100)+'%';}
function crumb(label){return `<p class="breadcrumb"><a href="#home">Learning space</a><span>/</span><strong>${e(label)}</strong></p>`;}
function sidebar(unit){$('#unit-nav').innerHTML=units.map(u=>`<a class="unit-nav-item ${u.id===unit?'active':''}" href="#unit/${u.id}" ${u.id===unit?'aria-current="page"':''}><span class="unit-number">0${u.id}</span><span>${e(u.title)}<small>${lessons.filter(l=>l.unit===u.id).length} lessons</small></span></a>`).join('');const page=location.hash.slice(1).split('/')[0]||'home';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});updateProgress();}
function dashboard(){const next=lessons.find(l=>!completed.has(l.id))||lessons[0];view.innerHTML=crumb('Dashboard')+`${storageWorks?'':'<p class="storage-warning">Browser storage is unavailable. You can still learn, but progress will not persist after this page closes.</p>'}<section class="dashboard-hero"><div><p class="eyebrow">A LITTLE PRACTICE. A CLEARER WAY OF THINKING.</p><h1>Build your logic.<br>One concept at a time.</h1><p class="lede">Understand the theory, trace an algorithm, and learn from your mistakes. Your Programming Logic and Design journey starts here.</p><div class="button-row"><a class="button" href="#lesson/${next.id}">${completed.size?'Continue learning':'Start learning'}</a><a class="button ghost" href="#lab">Open diagram lab</a></div><div class="hero-meta"><span>5 focused units</span><span>22 guided lessons</span><span>Learn at your pace</span></div></div><div class="hero-aside"><div class="hero-flow"><span class="mini-node round">Start</span><span>→</span><span class="mini-node">Think</span><span>→</span><span class="mini-node round">Build</span></div><strong>See how the pieces connect.</strong><p>Theory, pseudocode and diagrams,<br>in one learning space.</p></div></section><div class="stats"><div class="stat"><strong>05</strong><span>Learning units</span><small>A COMPLETE COURSE OUTLINE</small></div><div class="stat"><strong>22</strong><span>Debugging challenges</span><small>TRY BEFORE REVEALING</small></div><div class="stat"><strong>03</strong><span>Visual trace activities</span><small>WATCH THE STATE CHANGE</small></div><div class="stat"><strong>${completed.size}</strong><span>Lessons completed</span><small>SAVED ON THIS DEVICE</small></div></div><div class="section-heading"><h2>Your learning path</h2><p>Programming Logic &amp; Design</p></div><div class="unit-grid">${units.map(u=>{const ls=lessons.filter(l=>l.unit===u.id),done=ls.filter(l=>completed.has(l.id)).length;return `<article class="unit-card"><div class="unit-top"><span class="unit-badge">0${u.id}</span><span class="pill">${done===ls.length?'Completed':done?'In progress':'Ready to explore'}</span></div><h3>${e(u.title)}</h3><p>${e(u.subtitle)}</p><div class="topics">${u.themes.map(e).join(' · ')}</div><div class="card-bottom"><span>${ls.length} lessons · ${done} complete</span><a href="#unit/${u.id}">Explore unit</a></div></article>`}).join('')}</div><div class="section-heading"><h2>Learn by doing</h2><p>Tools for the tricky parts</p></div><div class="tools-grid"><article class="tool-card"><span class="tool-icon" aria-hidden="true">◇</span><div><h3>Pseudocode → flowchart</h3><p>Turn supported pseudocode into a visual flowchart or module hierarchy.</p><a href="#lab">Try the diagram lab</a></div></article><article class="tool-card"><span class="tool-icon" aria-hidden="true">▷</span><div><h3>Follow every step</h3><p>Watch counters, totals and array values change as an algorithm runs.</p><a href="#trace">Open the visualiser</a></div></article></div><div class="module-banner"><div><h3>One platform. More possibilities.</h3><p>PLD is the first module. C#, databases and web development can follow.</p></div><span class="pill">Future modules planned</span></div>`;sidebar();}
function unitPage(id){const u=units.find(u=>u.id===Number(id));if(!u){location.hash='home';return;}const ls=lessons.filter(l=>l.unit===u.id);view.innerHTML=crumb('Unit '+u.id)+`<p class="eyebrow">PROGRAMMING LOGIC &amp; DESIGN / UNIT 0${u.id}</p><h1>${e(u.title)}</h1><p class="lede">${e(u.subtitle)}. Each lesson combines original theory, a worked example, a knowledge check and an error-finding challenge.</p><div class="lesson-list">${ls.map((l,i)=>`<article class="lesson-row"><span class="sequence">${completed.has(l.id)?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${e(l.title)}</h3><p>${e(l.outcomes[0])}</p></div><a class="button secondary" href="#lesson/${l.id}">${completed.has(l.id)?'Review lesson':'Open lesson'}</a></article>`).join('')}</div><div class="note">You can learn in any order. Try the theory before attempting the exercises. Completion records practice; it is not a formal assessment result.</div>`;sidebar(u.id);}
function codeBlock(code,numbered=false){return `<pre><code>${numbered?code.split('\n').map((line,i)=>`<span class="line-code"><span class="ln">${i+1}</span>${e(line)}</span>`).join(''):e(code)}</code></pre>`;}
function lessonPage(id){const l=lessons.find(l=>l.id===id);if(!l){location.hash='home';return;}activeLesson=l;activeTab='theory';if(!states.has(id))states.set(id,{quizPassed:false,bugPassed:false,debugAttempts:0});view.innerHTML=crumb(`PLD / Unit ${l.unit}`)+`<div class="lesson-header"><p class="eyebrow">UNIT 0${l.unit} / GUIDED LESSON</p><h1>${e(l.title)}</h1><p class="lede">Understand it. Try it. Explain why it works.</p></div><div class="lesson-tabs" role="tablist" aria-label="Lesson sections">${[['theory','Theory & example'],['quiz','Knowledge check'],['debug','Find & fix errors']].map(([id,text])=>`<button role="tab" id="tab-${id}" aria-controls="lesson-panel" data-tab="${id}">${text}</button>`).join('')}</div><div class="lesson-layout"><section id="lesson-panel" class="panel" role="tabpanel"></section><aside class="panel objectives" style="position:static;height:auto;overflow:visible"><h3>Learning goals</h3><ul>${l.outcomes.map(o=>`<li>${e(o)}</li>`).join('')}</ul><div class="sidebar-divider"></div><h3>Lesson progress</h3><p id="lesson-progress" class="muted" style="font-size:11px"></p><a class="button secondary" href="#unit/${l.unit}">Back to unit ${l.unit}</a></aside></div><div class="completion"><p>Complete both checks correctly to mark this lesson complete.</p><button id="complete-lesson" class="button">Mark lesson complete</button></div><div class="button-row"><button id="print-lesson" class="button secondary">Print / save this view as PDF</button></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;renderLessonTab()}));$('#complete-lesson').addEventListener('click',()=>{const s=states.get(id);if(!s.quizPassed||!s.bugPassed)return;completed.add(id);save();updateLessonProgress();});$('#print-lesson').onclick=()=>window.print();renderLessonTab();sidebar(l.unit);}
function updateLessonProgress(){const l=activeLesson,s=states.get(l.id);$('#lesson-progress').textContent=`Knowledge check: ${s.quizPassed?'passed':'not yet passed'}. Error challenge: ${s.bugPassed?'passed':'not yet passed'}.`;const b=$('#complete-lesson');b.disabled=!(s.quizPassed&&s.bugPassed);b.textContent=completed.has(l.id)?'Lesson completed ✓':'Mark lesson complete';}
function renderLessonTab(){const l=activeLesson,s=states.get(l.id);document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===activeTab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',selected);});const panel=$('#lesson-panel');panel.setAttribute('aria-labelledby','tab-'+activeTab);
 if(activeTab==='theory'){panel.innerHTML=`<div class="theory">${l.sections.map(p=>`<h2>${e(p.heading)}</h2><p>${e(p.text)}</p>`).join('')}<h2>Worked example</h2><p>${l.diagram==='class'?'This example describes a class model. Class notation is taught here separately from the flowchart lab’s supported syntax.':'Follow the statements in order. Some examples assume input data or arrays already supplied by the problem.'}</p>${codeBlock(l.example)}${l.diagram==='none'?'':`<h2>${l.diagram==='hierarchy'?'Module hierarchy':l.diagram==='class'?'Class diagram example':'Flowchart'}</h2><div class="diagram" id="lesson-diagram"></div><p class="muted" style="font-size:11px">${l.diagram==='hierarchy'?'Arrows represent calls, not execution decisions. Uncalled methods are also displayed.':l.diagram==='class'?'An illustrative Learner-Course association. Minus means private; plus means public.':'Read labelled decisions and follow arrows. Scroll the diagram to inspect the full chart.'}</p>`}<div class="note">Convention: zero-based arrays; inclusive FOR bounds; TRUE/FALSE Boolean values. This is supplementary teaching content, not an institution-issued assessment.</div></div>`;if(l.diagram!=='none'){try{$('#lesson-diagram').innerHTML=l.diagram==='class'?classDiagram():l.diagram==='hierarchy'?hierarchy(parse(l.example)).svg:flowchart(parse(l.example));}catch(err){$('#lesson-diagram').textContent=err.message;}}}
 else if(activeTab==='quiz'){const q=l.quiz;panel.innerHTML=`<p class="eyebrow">CHECK YOUR UNDERSTANDING</p><form id="quiz-form"><fieldset><legend>${e(q.question)}</legend>${q.options.map((option,i)=>`<label class="quiz-option"><input required type="radio" name="quiz" value="${i}" ${s.quizChoice===i?'checked':''}><span>${e(option)}</span></label>`).join('')}</fieldset><div class="button-row"><button class="button" type="submit">Check answer</button></div><div class="feedback" id="quiz-feedback" role="status">${s.quizAttempt?`${s.quizPassed?'Correct.':'Not quite. Try again after reviewing the explanation.'} ${e(q.explanation)}`:''}</div></form>`;$('#quiz-form').onsubmit=event=>{event.preventDefault();s.quizChoice=Number(new FormData(event.currentTarget).get('quiz'));s.quizAttempt=true;s.quizPassed=s.quizChoice===q.correct;$('#quiz-feedback').textContent=(s.quizPassed?'Correct. ':'Not quite. ')+q.explanation;updateLessonProgress();};}
 else{const b=l.bug;panel.innerHTML=`<p class="eyebrow">DEBUGGING CHALLENGE</p><h2>Find the error. Explain the fix.</h2><p class="muted" style="font-size:12px">This example contains one deliberate error. Select its line, category and correction. The model answer unlocks after a complete attempt.</p>${codeBlock(b.code,true)}<form id="debug-form"><div class="debug-fields"><label class="field-label">Faulty line<select name="line" required><option value="">Choose a line</option>${b.code.split('\n').map((_,i)=>`<option value="${i+1}" ${s.line===i+1?'selected':''}>Line ${i+1}</option>`).join('')}</select></label><label class="field-label">Error category<select name="category" required><option value="">Choose a category</option>${['Syntax','Logic','Calculation','Boundary','Initialisation','Design'].map(c=>`<option ${s.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><fieldset><legend style="font-size:13px">Which correction fixes the stated problem?</legend>${b.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="correction" value="${i}" required ${s.correction===i?'checked':''}><span>${e(o)}</span></label>`).join('')}</fieldset><div class="button-row"><button type="submit" class="button">Check my attempt</button><button type="button" class="button secondary" id="debug-hint" ${s.debugAttempts?'':'disabled'}>Get a hint</button><button type="button" class="button ghost" id="reveal-answer" ${s.debugAttempts?'':'disabled'}>Reveal model answer</button></div><div id="debug-feedback" role="status" class="feedback">${s.debugFeedback?e(s.debugFeedback):''}</div><div id="debug-hint-text" class="note" hidden></div><div id="model-answer" class="model-answer" hidden><h3>Model answer</h3><p>Line ${b.line} · ${e(b.category)} error</p><code>${e(b.options[b.correct])}</code><p>${e(b.explanation)}</p></div></form>`;
 $('#debug-form').onsubmit=event=>{event.preventDefault();const fd=new FormData(event.currentTarget);if(!fd.get('line')||!fd.get('category')||fd.get('correction')===null)return;s.line=Number(fd.get('line'));s.category=String(fd.get('category'));s.correction=Number(fd.get('correction'));s.debugAttempts++;const checks=[s.line===b.line,s.category===b.category,s.correction===b.correct];const score=checks.filter(Boolean).length;s.bugPassed=score===3;s.debugFeedback=`${score} of 3 parts correct. Line: ${checks[0]?'correct':'review it'}. Category: ${checks[1]?'correct':'review it'}. Correction: ${checks[2]?'correct':'review it'}. ${score===3?'Well done. You can now read the full explanation.':'Try again, request a hint or reveal the model answer.'}`;$('#debug-feedback').textContent=s.debugFeedback;$('#debug-hint').disabled=false;$('#reveal-answer').disabled=false;updateLessonProgress();};$('#debug-hint').onclick=()=>{if(!s.debugAttempts)return;$('#debug-hint-text').hidden=false;$('#debug-hint-text').textContent=b.hint;};$('#reveal-answer').onclick=()=>{if(s.debugAttempts)$('#model-answer').hidden=false;};}
 updateLessonProgress();}
const samples={
 'Pass or revise':'BEGIN\n  INPUT mark\n  IF mark >= 50 THEN\n    OUTPUT "Pass"\n  ELSE\n    OUTPUT "Revise and try again"\n  ENDIF\nEND',
 'Counted loop':'BEGIN\n  SET total = 0\n  FOR i = 1 TO 3\n    INPUT value\n    SET total = total + value\n  ENDFOR\n  OUTPUT total\nEND',
 'Sentinel input':'BEGIN\n  INPUT value\n  WHILE value <> -1 DO\n    OUTPUT value\n    INPUT value\n  ENDWHILE\nEND',
 'Post-test loop':'BEGIN\n  REPEAT\n    INPUT age\n  UNTIL age >= 0\n  OUTPUT age\nEND',
 'CASE menu':'BEGIN\n  INPUT choice\n  CASE choice OF\n    WHEN 1:\n      OUTPUT "Add"\n    WHEN 2:\n      OUTPUT "Edit"\n    OTHERWISE:\n      OUTPUT "Unknown choice"\n  ENDCASE\nEND',
 'Module hierarchy':'PROCEDURE getInput()\n  INPUT value\nENDPROCEDURE\nPROCEDURE calculate()\n  SET result = value * 2\nENDPROCEDURE\nPROCEDURE showResult()\n  OUTPUT result\nENDPROCEDURE\nBEGIN\n  CALL getInput()\n  CALL calculate()\n  CALL showResult()\nEND'
};
let currentSVG='',lastAst=null;
function downloadBlob(bytes,type,name){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function labPage(){view.innerHTML=crumb('Diagram lab')+`<div class="lab-header"><p class="eyebrow">FROM ALGORITHM TO PICTURE</p><h1>See the logic take shape.</h1><p class="lede">Convert the documented pseudocode syntax into a flowchart or a module call hierarchy. Processing happens in your browser; no AI API is used.</p></div><div class="lab-controls"><label class="field-label">Load an example<select id="lab-example">${Object.keys(samples).map(s=>`<option>${e(s)}</option>`).join('')}</select></label><label class="field-label">Diagram type<select id="lab-type"><option value="flow">Flowchart</option><option value="hierarchy">Module hierarchy</option></select></label></div><div class="lab-grid"><section class="panel"><h2>Your pseudocode</h2><label class="field-label" for="pseudocode">Edit the algorithm<textarea id="pseudocode" class="editor" spellcheck="false" maxlength="16000">${e(samples['Pass or revise'])}</textarea></label><div class="button-row"><button class="button" id="generate-chart">Generate diagram</button></div><p class="status" id="lab-status" role="status"></p><label class="field-label">Flowchart section<select id="lab-module"><option value="main">Main program</option></select></label></section><section class="panel"><h2>Your diagram</h2><div class="diagram-toolbar"><button class="button secondary" id="download-svg" disabled>Download SVG</button><button class="button secondary" id="download-png" disabled>Download PNG</button><button class="button secondary" id="diagram-pdf" disabled>Print / PDF</button><button class="button secondary" id="fit-chart" disabled>Fit width</button></div><div id="lab-diagram" class="diagram"><div class="diagram-placeholder"><span>◇</span><p>Your diagram will appear here.<br>Choose an example and generate it.</p></div></div></section></div><details class="syntax panel"><summary>Supported syntax and limits</summary><p>The converter checks recognised statements and matching block boundaries. It does not execute expressions, validate types or prove that an algorithm is correct. Keywords are case-insensitive. Use one statement per line.</p><div class="scroll-table"><table><thead><tr><th>Structure</th><th>Notation</th></tr></thead><tbody><tr><td>Program</td><td><code>BEGIN</code> ... <code>END</code></td></tr><tr><td>Input and output</td><td><code>INPUT name</code> / <code>OUTPUT "Hello", name</code></td></tr><tr><td>Assignment and declaration</td><td><code>SET total = total + value</code> / <code>DECLARE total AS REAL</code></td></tr><tr><td>Selection</td><td><code>IF condition THEN</code> ... <code>ELSE</code> ... <code>ENDIF</code>. For another condition, nest IF inside ELSE.</td></tr><tr><td>Counted loop</td><td><code>FOR i = 1 TO 5 STEP 1</code> ... <code>ENDFOR</code>. STEP must be a nonzero integer; it defaults to 1.</td></tr><tr><td>Conditional loops</td><td><code>WHILE condition DO</code> ... <code>ENDWHILE</code> / <code>REPEAT</code> ... <code>UNTIL condition</code></td></tr><tr><td>CASE</td><td><code>CASE expression OF</code>, <code>WHEN value:</code>, <code>OTHERWISE:</code>, <code>ENDCASE</code>. Displayed as equivalent chained decisions.</td></tr><tr><td>Methods</td><td><code>PROCEDURE name(parameters)</code> ... <code>ENDPROCEDURE</code> or <code>FUNCTION name(parameters) RETURNS REAL</code> ... <code>ENDFUNCTION</code>. Define methods outside BEGIN/END.</td></tr><tr><td>Calls and returns</td><td><code>CALL name(arguments)</code>. Hierarchy view also recognises defined function names inside expressions. RETURN is parsed for hierarchy view; flowcharts containing RETURN are not supported yet.</td></tr><tr><td>Comments</td><td>Whole lines beginning with <code>//</code>. Maximum 180 non-empty lines and six levels of nesting.</td></tr></tbody></table></div><p>Hierarchy charts show call relationships, including recursion; uncalled methods are shown separately. Undefined calls are reported. Class syntax, overload resolution, ELSEIF, BREAK and CONTINUE are not supported in this release. Use the class diagrams in Unit 5 for object-oriented examples.</p></details>`;sidebar();
 const editor=$('#pseudocode'),type=$('#lab-type'),module=$('#lab-module'),status=$('#lab-status');currentSVG='';lastAst=null;
 function invalidate(){currentSVG='';lastAst=null;['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=true);$('#lab-diagram').innerHTML='<div class="diagram-placeholder"><span>◇</span><p>Your code has changed. Generate a fresh diagram.</p></div>';status.textContent='';}
 function draw(){try{lastAst=parse(editor.value);const selected=module.value;module.innerHTML='<option value="main">Main program</option>'+lastAst.modules.map(m=>`<option value="${e(m.name)}">${e(m.name)}</option>`).join('');if([...module.options].some(o=>o.value===selected))module.value=selected;let notice='';if(type.value==='hierarchy'){const result=hierarchy(lastAst);currentSVG=result.svg;if(result.missing.length)notice=' Undefined calls: '+result.missing.join(', ')+'. These are shown without a definition.';}else currentSVG=flowchart(lastAst,module.value);$('#lab-diagram').innerHTML=currentSVG;$('#lab-diagram').classList.remove('fit');$('#fit-chart').textContent='Fit width';status.textContent='Diagram generated from the supported syntax.'+notice;module.disabled=type.value==='hierarchy';['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=false);}catch(err){currentSVG='';$('#lab-diagram').innerHTML='<div class="diagram-placeholder"><span>!</span><p>Check the editor feedback, correct the code and try again.</p></div>';status.textContent=err.message;['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=true);}}
 $('#lab-example').onchange=event=>{editor.value=samples[event.target.value];type.value=event.target.value==='Module hierarchy'?'hierarchy':'flow';module.value='main';invalidate();};editor.oninput=invalidate;type.onchange=()=>{module.disabled=type.value==='hierarchy';invalidate();};$('#generate-chart').onclick=draw;module.onchange=draw;
 $('#download-svg').onclick=()=>{if(currentSVG)downloadBlob(currentSVG,'image/svg+xml','LogicLab-diagram.svg')};$('#fit-chart').onclick=()=>{const fit=$('#lab-diagram').classList.toggle('fit');$('#fit-chart').textContent=fit?'Actual size':'Fit width';};
 $('#download-png').onclick=async()=>{if(!currentSVG)return;const button=$('#download-png');button.disabled=true;try{const svg=currentSVG;const img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});const scale=Math.min(2,6000/img.width,10000/img.height,Math.sqrt(18000000/(img.width*img.height)));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error();downloadBlob(blob,'image/png','LogicLab-diagram.png');status.textContent='PNG prepared. Check your downloads.';}finally{URL.revokeObjectURL(url)}}catch{status.textContent='PNG could not be created. Try the SVG download instead.';}finally{button.disabled=!currentSVG;}};
 $('#diagram-pdf').onclick=()=>{if(!currentSVG)return;document.body.classList.add('print-diagram');window.print();};window.onafterprint=()=>document.body.classList.remove('print-diagram');}
function traceData(kind){if(kind==='sum'){let states=[{line:1,vars:{total:0,i:'-'},output:'',note:'Initialise total before the loop.'}];let total=0;for(let i=1;i<=3;i++){states.push({line:2,vars:{total,i},output:'',note:`The loop condition is true for i = ${i}.`});total+=i;states.push({line:3,vars:{total,i},output:'',note:`Add ${i} to the running total.`})}states.push({line:2,vars:{total,i:4},output:'',note:'i is now 4. The upper bound is 3, so the loop ends.'},{line:5,vars:{total,i:4},output:String(total),note:'Display the final total after the loop.'});return{code:'SET total = 0\nFOR i = 1 TO 3\n  SET total = total + i\nENDFOR\nOUTPUT total',states};}
 if(kind==='search'){const a=[8,3,11,5],states=[{line:1,vars:{i:0,foundAt:-1},array:a,compare:[],output:'',note:'Search for 11. Initialise the result to -1.'}];for(let i=0;i<a.length;i++){states.push({line:3,vars:{i,foundAt:i>2?2:-1},array:a,compare:[i],output:'',note:`Compare values[${i}] (${a[i]}) with 11.`});if(a[i]===11)states.push({line:4,vars:{i,foundAt:i},array:a,compare:[i],output:'',note:'A match is found at index 2. Store its position.'});}states.push({line:7,vars:{i:4,foundAt:2},array:a,compare:[],output:'2',note:'The full traversal is complete. Display the match position.'});return{code:'SET foundAt = -1\nFOR i = 0 TO 3\n  IF values[i] = 11 THEN\n    SET foundAt = i\n  ENDIF\nENDFOR\nOUTPUT foundAt',states};}
 const a=[5,2,4,1],states=[{line:1,vars:{pass:0,j:'-'},array:[...a],compare:[],output:'',note:'Start with four unsorted values.'}];for(let p=0;p<a.length-1;p++)for(let j=0;j<a.length-1-p;j++){states.push({line:3,vars:{pass:p,j},array:[...a],compare:[j,j+1],output:'',note:`Compare adjacent values ${a[j]} and ${a[j+1]}.`});if(a[j]>a[j+1]){[a[j],a[j+1]]=[a[j+1],a[j]];states.push({line:6,vars:{pass:p,j},array:[...a],compare:[j,j+1],output:'',note:'Swap the pair using a temporary value.'})}}states.push({line:10,vars:{pass:3,j:'-'},array:[...a],compare:[],output:a.join(', '),note:'The array is now sorted in ascending order.'});return{code:'FOR pass = 0 TO 2\n  FOR j = 0 TO 2 - pass\n    IF values[j] > values[j + 1] THEN\n      SET temp = values[j]\n      SET values[j] = values[j + 1]\n      SET values[j + 1] = temp\n    ENDIF\n  ENDFOR\nENDFOR\nOUTPUT values',states};}
function tracePage(){view.innerHTML=crumb('Visual step-through')+`<p class="eyebrow">WATCH THE PROGRAM STATE</p><h1>Slow it down. See every change.</h1><p class="lede">These guided traces use fixed examples. They do not execute arbitrary pasted pseudocode.</p><label class="field-label" style="max-width:400px">Choose an algorithm<select id="trace-example"><option value="sum">A loop and a running total</option><option value="search">Linear search in an array</option><option value="sort">Bubble sort, one comparison at a time</option></select></label><div id="trace-view"></div>`;sidebar();let step=0,data=traceData('sum');function render(){const s=data.states[step];$('#trace-view').innerHTML=`<div class="trace-grid"><section class="panel"><h2>The algorithm</h2><pre><code>${data.code.split('\n').map((line,i)=>`<span class="line-code ${i+1===s.line?'trace-current':''}"><span class="ln">${i+1}</span>${e(line)}</span>`).join('')}</code></pre><div class="button-row"><button class="button secondary" id="trace-prev" ${step===0?'disabled':''}>Previous step</button><button class="button" id="trace-next" ${step===data.states.length-1?'disabled':''}>Next step</button><button class="button secondary" id="trace-reset">Restart</button></div><p class="status" role="status">Step ${step+1} of ${data.states.length}</p></section><section class="panel"><h2>Current state</h2><div class="trace-variables">${Object.entries(s.vars).map(([key,value])=>`<div class="variable"><span>${e(key)}</span><strong>${e(value)}</strong></div>`).join('')}</div>${s.array?`<div class="array-cells">${s.array.map((v,i)=>`<div class="array-cell ${s.compare.includes(i)?'compare':''}"><small style="font-size:9px;display:block;color:#87909c">[${i}]</small>${v}</div>`).join('')}</div>`:''}<p class="trace-description" role="status">${e(s.note)}</p><h3 style="font-size:12px">Output</h3><div class="trace-output">${e(s.output||'No output yet')}</div><h3 style="font-size:12px;margin-top:25px">Trace history</h3><div class="scroll-table"><table class="trace-history"><thead><tr><th>Step</th><th>Line</th><th>Variables</th></tr></thead><tbody>${data.states.slice(0,step+1).map((t,i)=>`<tr><td>${i+1}</td><td>${t.line}</td><td>${e(Object.entries(t.vars).map(([k,v])=>k+' = '+v).join(', '))}</td></tr>`).join('')}</tbody></table></div></section></div>`;$('#trace-prev').onclick=()=>{step--;render()};$('#trace-next').onclick=()=>{step++;render()};$('#trace-reset').onclick=()=>{step=0;render()};}$('#trace-example').onchange=event=>{data=traceData(event.target.value);step=0;render()};render();}
function about(){view.innerHTML=crumb('About & privacy')+`<p class="eyebrow">LOGICLAB / FIRST RELEASE</p><h1>Built to make the logic clearer.</h1><div class="panel theory"><h2>About the course</h2><p>LogicLab is an independent supplementary learning platform by Lefa Malatji. Its Programming Logic and Design content follows the five-unit outline supplied for this project. Explanations and practice questions are original; the platform is not an official institutional course or assessment.</p><h2>Language and review</h2><p>This first release is in English. Reviewed Sepedi explanations and additional modules are planned. Teaching content and diagram behaviour should be reviewed before use in assessed work.</p><h2>Your progress and privacy</h2><p>Completed lesson IDs are saved in localStorage on this browser when available. They are not sent to a server or synchronised across devices. Reset progress removes these stored completion marks. Exercise selections and pseudocode remain in page memory; diagrams are generated locally.</p><h2>Practice, not secure assessment</h2><p>Solutions are hidden in the interface until a complete attempt is submitted. Because this is a browser-only application, a determined user can inspect downloaded source files to find answers. It is not a secure examination system.</p><h2>Current boundaries</h2><p>The diagram lab supports a documented subset, not every pseudocode dialect. It validates structure but does not prove an algorithm correct. Guided visual traces use fixed examples. There are no student accounts, lecturer dashboards or cross-device progress in this version.</p><h2>Contact</h2><p>Report a content or website issue to <a style="color:var(--purple);text-decoration:underline" href="mailto:lazylefa@gmail.com?subject=LogicLab%20feedback">lazylefa@gmail.com</a>.</p><a class="button" href="#home">Back to learning</a></div>`;sidebar();}
function route(){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('print-diagram');const[page,id]=location.hash.slice(1).split('/');if(page==='unit')unitPage(id);else if(page==='lesson')lessonPage(id);else if(page==='lab')labPage();else if(page==='trace')tracePage();else if(page==='about')about();else dashboard();window.scrollTo({top:0,behavior:'instant'});document.title=(page==='lesson'?activeLesson?.title:page==='lab'?'Diagram lab':page==='trace'?'Visual step-through':'Programming Logic and Design')+' | LogicLab';$('#main').focus({preventScroll:true});}
$('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',open);};document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});$('#reset-progress').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{completed.clear();save();$('#reset-dialog').close();route();};window.addEventListener('hashchange',route);route();
